import{_ as a,o as t,c as s,ai as e}from"./chunks/framework.ETupdKIa.js";const _=JSON.parse('{"title":"immutableとは？","description":"","frontmatter":{"title":"immutableとは？","date":"2025-12-23T00:00:00.000Z","status":"published"},"headers":[],"relativePath":"til/Java/20251223_immutableとは？.md","filePath":"til/Java/20251223_immutableとは？.md"}'),l={name:"til/Java/20251223_immutableとは？.md"};function n(r,i,p,h,m,k){return t(),s("div",null,[...i[0]||(i[0]=[e(`<h1 id="_20251223-immutableとは" tabindex="-1">20251223_immutableとは？ <a class="header-anchor" href="#_20251223-immutableとは" aria-label="Permalink to “20251223_immutableとは？”">​</a></h1><p>mutableは「変更可能な」を意味するので、immutableは「変更不可能な」を意味する。</p><p>Javaにおけるimmutableとは、「オブジェクトの状態（フィールド）が書き換わることがない」を意味する。例えば、Stringはimmutableなクラスであり、以下に説明用のコードを記載する。</p><div class="language-java"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String str </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;str&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">str </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>このプログラムにおいては、変数strは、まず”str”を参照し、次に”ing”を参照する。このとき、もともと参照していた”str”が”ing”に書き換わるのではなく、”str”はそのまま、”ing”が新しく生成され、変数strの参照先が変わるだけである。</p><p>このように、もともと存在するオブジェクトの状態（フィールド）が変わらないクラスを、immutableなクラスという。</p>`,6)])])}const o=a(l,[["render",n]]);export{_ as __pageData,o as default};
